#include <vector>
#include <algorithm>
#include <iostream>

int main() {
    std::vector<int> coll1 = {1, 2, 3, 4, 5};
    std::vector<int> coll2(5); // pre-sized destination collection

    // Copy elements from coll1 to coll2 using iterators
    std::copy(coll1.begin(), coll1.end(), coll2.begin());

    // Output the contents of coll2
    for (const auto& val : coll2) {
        std::cout << val << ' ';
    }
    return 0;
}
